import backtrader as bt


class KeltnerWilliamsRStrategy(bt.Strategy):
    params = (
        ("ema_period", 20),
        ("atr_period", 14),
        ("keltner_mult", 2.0),
        ("willr_period", 14),
        ("stop_atr_mult", 1.5),
    )

    def __init__(self):
        self.ema = bt.indicators.EMA(self.data.close, period=self.p.ema_period)
        self.atr = bt.indicators.ATR(self.data, period=self.p.atr_period)
        self.upper_band = self.ema + self.p.keltner_mult * self.atr
        self.lower_band = self.ema - self.p.keltner_mult * self.atr
        self.willr = bt.indicators.WilliamsR(self.data, period=self.p.willr_period)

        self.order = None
        self.stop_order = None

    def notify_order(self, order):
        if order.status in [order.Submitted, order.Accepted]:
            return

        if order.status in [order.Completed]:
            if order == self.order:
                self.order = None
                if self.position.size > 0:
                    stop_price = order.executed.price - self.p.stop_atr_mult * self.atr[0]
                    self.stop_order = self.sell(exectype=bt.Order.Stop, price=stop_price)
                elif self.position.size < 0:
                    stop_price = order.executed.price + self.p.stop_atr_mult * self.atr[0]
                    self.stop_order = self.buy(exectype=bt.Order.Stop, price=stop_price)
                else:
                    if self.stop_order:
                        self.cancel(self.stop_order)
                        self.stop_order = None
            elif order == self.stop_order:
                self.stop_order = None

        elif order.status in [order.Canceled, order.Margin, order.Rejected]:
            if order == self.order:
                self.order = None
            if order == self.stop_order:
                self.stop_order = None

    def next(self):
        if self.order:
            return

        if not self.position:
            if self.data.close[0] < self.lower_band[0] and self.willr[0] < -80:
                self.order = self.buy()
            elif self.data.close[0] > self.upper_band[0] and self.willr[0] > -20:
                self.order = self.sell()
        else:
            if self.position.size > 0:
                if self.data.close[0] >= self.ema[0]:
                    if self.stop_order:
                        self.cancel(self.stop_order)
                        self.stop_order = None
                    self.order = self.close()
            elif self.position.size < 0:
                if self.data.close[0] <= self.ema[0]:
                    if self.stop_order:
                        self.cancel(self.stop_order)
                        self.stop_order = None
                    self.order = self.close()
